create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,full_name text,role text not null default 'editor' check(role in('administrator','editor','sales')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.profiles enable row level security;create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role in('administrator','editor','sales'))$$;revoke all on function public.is_staff() from public;grant execute on function public.is_staff() to authenticated;create policy "staff read profiles" on public.profiles for select to authenticated using(public.is_staff());create policy "staff read contacts" on public.contacts for select to authenticated using(public.is_staff());create policy "staff read leads" on public.leads for select to authenticated using(public.is_staff());create policy "staff update leads" on public.leads for update to authenticated using(public.is_staff()) with check(public.is_staff());create policy "staff read lead activities" on public.lead_activities for select to authenticated using(public.is_staff());create policy "staff insert lead activities" on public.lead_activities for insert to authenticated with check(public.is_staff());